    'Requires a Torbox API key. Debrify issues a fast cache check after each search; if anything fails, Torbox buttons remain enabled so you can still try.': '需要 TorBox API 密钥。每次搜索后 Debrify 会快速检查缓存；若检查失败，TorBox 按钮仍可用，你仍可尝试。',
    'Try sources from top to bottom for your subtitle language. No Preference tries English first, then another available track within the same source.': '按从上到下的顺序尝试字幕语言来源。「无偏好」会先试英语，再试同一来源的其他可用轨道。',
    'Choose a name such as “Living room TV”. It will appear on your connected devices. To rename another device, open this setting on that device.': '选择一个名称，例如「客厅电视」。它会显示在已连接设备上。要重命名其他设备，请在该设备上打开此设置。',
    'Verify Torbox has a cached copy before enabling quick actions in torrent search results. Non-cached torrents keep the Torbox button available.': '在种子搜索结果中启用快捷操作前，先确认 TorBox 是否有缓存副本。未缓存的种子仍会保留 TorBox 按钮。',
    'Plays once, then holds its final frame while Home loads. Artwork is fitted without cropping. Imported colors do not follow the app theme.': '播放一次，然后在首页加载时保持最后一帧。画面适配不裁剪。导入的颜色不会跟随应用主题。',
    'IPTV playlists, favorites and watch history sync automatically. Channel listings and TV guides are downloaded separately on each device.': 'IPTV 播放列表、收藏与观看记录会自动同步。频道列表与电视指南在每台设备上单独下载。',
    'This removes profiles, credentials, settings, jobs, and private app data. Completed media files are retained. This cannot be undone.': '将删除个人资料、凭据、设置、任务与私有应用数据。已完成的媒体文件会保留。此操作无法撤销。',
    'This device only. Saves one rolling file in logs/ every 5 minutes while the app is open. Anyone with folder access can read it.': '仅本设备。应用打开时每 5 分钟在 logs/ 写入一个滚动文件。有文件夹访问权限的人都可以读取。',
    'To show Real Debrid in navigation again, you must logout and login. This is a security measure to prevent unauthorized changes.': '要在导航中再次显示 Real-Debrid，必须退出并重新登录。这是防止未经授权更改的安全措施。',
    'To change the folder restriction, you must logout and login again. This is a security measure to prevent unauthorized changes.': '要更改文件夹限制，必须退出并重新登录。这是防止未经授权更改的安全措施。',
    'To remove the folder restriction, you must logout and login again. This is a security measure to prevent unauthorized changes.': '要移除文件夹限制，必须退出并重新登录。这是防止未经授权更改的安全措施。',
    'To show Premiumize in navigation again, you must logout and login. This is a security measure to prevent unauthorized changes.': '要在导航中再次显示 Premiumize，必须退出并重新登录。这是防止未经授权更改的安全措施。',
    'Connect public or private indexers through Jackett and Prowlarr. Enabled engines appear in the torrent search source picker.': '通过 Jackett 和 Prowlarr 连接公共或私有索引。启用的引擎会出现在种子搜索来源选择器中。',
    'Pick a year and month, then browse only the days that actually have episodes airing. No grid, no jitter, just the schedule.': '选择年月，然后只浏览真正有剧集播出的日期。无网格、无抖动，只有日程。',
    'To show PikPak in navigation again, you must logout and login. This is a security measure to prevent unauthorized changes.': '要在导航中再次显示 PikPak，必须退出并重新登录。这是防止未经授权更改的安全措施。',
    'To show Torbox in navigation again, you must logout and login. This is a security measure to prevent unauthorized changes.': '要在导航中再次显示 TorBox，必须退出并重新登录。这是防止未经授权更改的安全措施。',
    'You can also send an animation from a paired Debrify phone or computer. Open its imported animation and choose Send to TV.': '也可以从已配对的 Debrify 手机或电脑发送动画。打开已导入的动画并选择发送到电视。',
    'Channels and saved torrent pools transfer only when you sync them here. Run this on both devices after changing channels.': '频道与已保存的种子池仅在此处同步时才会传输。更改频道后请在两端设备上运行此操作。',
    'For extra privacy, Debrify can access one chosen folder instead of your whole PikPak drive. You can skip this now.': '为增强隐私，Debrify 可只访问选定文件夹，而不是整个 PikPak 网盘。你现在可以跳过。',
    'No torrent engines or streaming addons installed yet — add some from the Addons hub and they will appear here.': '尚未安装种子引擎或流媒体插件 — 从插件中心添加后会显示在这里。',
    'Paste the addon manifest URL. Configure the addon on its website first, then paste the personalized URL here.': '粘贴插件清单网址。请先在其网站配置插件，再将个性化网址粘贴到此处。',
    'Setup items apply to the receiving device’s active profile. Keep both apps open and confirm the import there.': '设置项应用于接收设备的当前个人资料。请保持两端应用打开并在该处确认导入。',
    'Setup items apply to the receiving device\'s active profile. Keep both apps open and confirm the import there.': '设置项应用于接收设备的当前个人资料。请保持两端应用打开并在该处确认导入。',
